CREATE TABLE IF NOT EXISTS point_accounts (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,balance BIGINT NOT NULL DEFAULT 0 CHECK(balance>=0),lifetime_earned BIGINT NOT NULL DEFAULT 0,lifetime_spent BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS post_game_stats (post_id UUID PRIMARY KEY REFERENCES posts(id) ON DELETE CASCADE,points BIGINT NOT NULL DEFAULT 50 CHECK(points>=0),shield_expires_at TIMESTAMP,booster_expires_at TIMESTAMP,last_steal_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS point_transactions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),source_user_id UUID REFERENCES users(id) ON DELETE SET NULL,target_user_id UUID REFERENCES users(id) ON DELETE SET NULL,source_post_id UUID REFERENCES posts(id) ON DELETE SET NULL,target_post_id UUID REFERENCES posts(id) ON DELETE SET NULL,amount BIGINT NOT NULL CHECK(amount>0),type VARCHAR(40) NOT NULL,reason TEXT,reference_id UUID,idempotency_key VARCHAR(160) UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS king_sessions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,post_id UUID REFERENCES posts(id) ON DELETE CASCADE,started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,ended_at TIMESTAMP,duration_seconds BIGINT);
CREATE TABLE IF NOT EXISTS king_bounties (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),period_key VARCHAR(32) UNIQUE NOT NULL,king_user_id UUID REFERENCES users(id) ON DELETE SET NULL,king_post_id UUID REFERENCES posts(id) ON DELETE SET NULL,amount BIGINT DEFAULT 500,paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS duels (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),player_1 UUID REFERENCES users(id) ON DELETE CASCADE,player_2 UUID REFERENCES users(id) ON DELETE SET NULL,entry_amount BIGINT NOT NULL CHECK(entry_amount>0),pot BIGINT NOT NULL DEFAULT 0,player_1_score BIGINT DEFAULT 0,player_2_score BIGINT DEFAULT 0,started_at TIMESTAMP,ends_at TIMESTAMP,status VARCHAR(20) DEFAULT 'waiting' CHECK(status IN('waiting','active','finished','cancelled')),winner_id UUID REFERENCES users(id) ON DELETE SET NULL,payout_status VARCHAR(20) DEFAULT 'pending' CHECK(payout_status IN('pending','paid','void')),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS duel_participants (duel_id UUID REFERENCES duels(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(duel_id,user_id));
CREATE TABLE IF NOT EXISTS inventory_items (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,item_type VARCHAR(40) NOT NULL,quantity INTEGER DEFAULT 0 CHECK(quantity>=0),metadata JSONB DEFAULT '{}'::jsonb,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,item_type));
CREATE TABLE IF NOT EXISTS quests (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),quest_key VARCHAR(80) UNIQUE NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,target INTEGER NOT NULL,reward BIGINT NOT NULL,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS quest_progress (user_id UUID REFERENCES users(id) ON DELETE CASCADE,quest_id UUID REFERENCES quests(id) ON DELETE CASCADE,period_key VARCHAR(32),progress INTEGER DEFAULT 0,completed BOOLEAN DEFAULT FALSE,claimed BOOLEAN DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,quest_id,period_key));
CREATE TABLE IF NOT EXISTS shop_items (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),item_key VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,description TEXT,cost BIGINT NOT NULL,item_type VARCHAR(40) NOT NULL,metadata JSONB DEFAULT '{}'::jsonb,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS shop_purchases (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,shop_item_id UUID REFERENCES shop_items(id),cost BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS spin_claims (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,last_spin_at TIMESTAMP,next_spin_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS reward_claims (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,reward_type VARCHAR(40),reference_key VARCHAR(160),amount BIGINT DEFAULT 0,metadata JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,reward_type,reference_key));
CREATE TABLE IF NOT EXISTS referrals (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),referrer_id UUID REFERENCES users(id) ON DELETE CASCADE,visitor_fingerprint VARCHAR(255),visitor_user_id UUID REFERENCES users(id) ON DELETE SET NULL,visit_rewarded BOOLEAN DEFAULT FALSE,signup_rewarded BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO quests(quest_key,title,description,target,reward) VALUES ('daily_post','Create 1 Post','Create a post today',1,100),('daily_like_10','Hot 10','React to 10 posts today',10,250),('daily_comment_5','Commentator','Comment 5 times today',5,150),('daily_share_3','Sharer','Share 3 posts today',3,250),('daily_duel_1','Warrior','Play 1 duel today',1,300) ON CONFLICT(quest_key) DO NOTHING;
INSERT INTO shop_items(item_key,name,description,cost,item_type,metadata) VALUES ('glow_frame','Glow Frame','Premium avatar glow frame',1500,'cosmetic','{"cosmetic":"frame"}'),('vip_badge','VIP Badge','VIP profile badge',5000,'cosmetic','{"cosmetic":"badge"}'),('gold_username','Gold Username','Gold username style',2500,'cosmetic','{"cosmetic":"username"}'),('shield','Shield x1','1 hour theft protection',700,'consumable','{"item":"shield"}'),('booster_2x','2X Booster','Double qualifying rewards',1200,'consumable','{"item":"booster"}'),('mystery_box','Mystery Box','Random reward',1000,'loot','{"item":"loot"}') ON CONFLICT(item_key) DO NOTHING;
INSERT INTO point_accounts(user_id) SELECT id FROM users ON CONFLICT(user_id) DO NOTHING;
INSERT INTO post_game_stats(post_id,points) SELECT id,50 FROM posts WHERE is_deleted=false ON CONFLICT(post_id) DO NOTHING;
CREATE INDEX IF NOT EXISTS idx_pgs_points ON post_game_stats(points DESC); CREATE INDEX IF NOT EXISTS idx_pt_user ON point_transactions(source_user_id,target_user_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_duels_status ON duels(status,ends_at);
ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_type_check;
ALTER TABLE notifications ADD CONSTRAINT notifications_type_check CHECK(type IN('follow','like','comment','reply','share','mention','message','story_reply','story_reaction','follow_request','system','gift','steal','king','duel','quest','reward','shield','booster','referral'));
